function same(a,b){ return JSON.stringify(a)===JSON.stringify(b); }
function reg(p,base,lbl){ if(!BASE.hasOwnProperty(p)){ BASE[p]=base; LBL[p]=lbl||p; } }
function val(p){ return DRAFT.hasOwnProperty(p)? DRAFT[p] : BASE[p]; }
function chg(p){ return DRAFT.hasOwnProperty(p); }
function set(p,v){ if(typeof BASE[p]==="number"){ v=Number(v); if(isNaN(v)) v=BASE[p]; } if(same(v,BASE[p])) delete DRAFT[p]; else DRAFT[p]=v; topbar(); go(); }
