function chgPre(pre){ return Object.keys(DRAFT).some(function(p){ return p.indexOf(pre)===0; }); }
function toast(t){ var d=document.createElement("div"); d.className="toast"; d.textContent=t; document.body.appendChild(d); setTimeout(function(){d.remove()},2200); }
function T(t){ return function(){ toast(t); }; }
function modal(f){ ST.modal=f||null; go(); }
