function mover(d){ if(HP+d<0 || HP+d>=HIST.length) return; HP+=d; var o=JSON.parse(HIST[HP]); ST.sec=o.sec; ST.sel=o.sel; ST.tab=o.tab; ST.modal=null; MOV=true; go(); MOV=false; $("main").scrollTop=0; }
