function fld(p,lbl,base,o){
  o=o||{}; reg(p,base,o.full||lbl); var v=val(p), c=chg(p), h, k=c?" chg":"";
  var S=function(x){ set(p,x); };
  if(o.type==="range") h='<div class="rng"><input type="range" min="'+o.min+'" max="'+o.max+'" step="'+(o.step||1)+'" value="'+v+'" oninput="this.nextElementSibling.value=this.value" onchange="'+on(S)+'"><input type="number" min="'+o.min+'" max="'+o.max+'" step="'+(o.step||1)+'" value="'+v+'" onchange="'+on(function(x){ S(clamp(Number(x),o.min,o.max)); })+'"></div>';
  else if(o.type==="color") h='<div class="row"><input type="color" value="'+v+'" onchange="'+on(S)+'" style="width:44px;height:30px;padding:0;border:0;background:none"><span class="mono small">'+esc(v)+'</span></div>';
  else if(o.type==="sel") h='<select onchange="'+on(function(x){ S(x==="—"?null:x); })+'">'+o.opts.map(function(x){return '<option'+(x===(v==null?"—":v)?" selected":"")+'>'+esc(x)+'</option>'}).join("")+'</select>';
  else if(o.type==="area") h='<textarea rows="'+(o.rows||2)+'" onchange="'+on(S)+'">'+esc(v)+'</textarea>';
  else if(o.type==="tog") h='<div class="row">'+sw(!!v,function(){ S(!v); })+'<span class="small mut">'+(v?(o.si||"Sí"):(o.no||"No"))+'</span></div>';
  else if(o.type==="multi") h='<div>'+o.opts.map(function(x){ var a=(v||[]); var onx=a.indexOf(x)>=0; return '<span class="chip '+(onx?"on":"")+'" onclick="'+on(function(){ var n=a.slice(); if(onx) n.splice(n.indexOf(x),1); else n.push(x); S(o.nullEmpty&&!n.length? null : n); })+'">'+esc(x)+'</span>'; }).join("")+(o.nullEmpty&&!(v||[]).length?'<span class="small mut">todas</span>':'')+'</div>';
  else if(o.type==="list") h='<textarea rows="'+Math.min(8,Math.max(2,(v||[]).length))+'" onchange="'+on(function(x){ S(x.split("\n").map(function(s){return s.trim()}).filter(Boolean)); })+'">'+esc((v||[]).join("\n"))+'</textarea>';
  else h='<input type="'+(typeof base==="number"?"number":"text")+'" value="'+esc(v)+'" '+(o.min!==undefined?'min="'+o.min+'" max="'+o.max+'" step="'+(o.step||"any")+'"':'')+' onchange="'+on(function(x){ S(o.min!==undefined? clamp(Number(x),o.min,o.max) : x); })+'">';
  return '<div class="f"><label>'+esc(lbl)+(o.d?'<small>'+esc(o.d)+'</small>':'')+'</label><div class="'+k+'">'+h+'</div><div class="fab">'+(c?'fábrica: '+esc(shw(BASE[p]))+' · <a onclick="'+on(function(){ S(BASE[p]); })+'">deshacer</a>':(o.min!==undefined?'rango '+nf(o.min)+' – '+nf(o.max):(o.hint||'')))+'</div></div>';
}
/* celda editable para tablas */
function cel(p,base,o){ o=o||{}; reg(p,base,o.full); var v=val(p); if(o.opts) return '<select class="'+(chg(p)?"chg":"")+'" style="width:'+(o.w||84)+'px" onchange="'+on(function(x){set(p,x)})+'">'+o.opts.map(function(x){return '<option'+(x===v?" selected":"")+'>'+x+'</option>'}).join("")+'</select>';
  return '<input class="'+(chg(p)?"chg":"")+'" type="'+(typeof base==="number"?"number":"text")+'" value="'+esc(v)+'" '+(o.min!==undefined?'min="'+o.min+'" max="'+o.max+'" step="'+(o.step||"any")+'"':'')+' style="width:'+(o.w||70)+'px" onchange="'+on(function(x){ set(p, o.min!==undefined? clamp(Number(x),o.min,o.max) : x); })+'">'; }
