var FXN={nota:"Nota",opp:"Producción rival ×",own:"Producción propia ×",ta:"Amarilla",roja:"Roja",mis:"Míster",disc:"Disciplina",ego:"Ego",afin:"Afinidad",lesion:"Lesión",comp:"Compañerismo",lid:"Liderazgo",entra:"Entrar al campo",gol:"Gol",golR:"Gol en contra",asis:"Asistencia",parada:"Parada",lider:"Liderazgo ×",resil:"Resiliencia ×",regen:"Recuperación",modLes:"Riesgo de lesión",conf:"Confianza",seg:"Seguidores",robo:"Robo",vicio:"Vicio",seguro:"Seguro",confYa:"Confianza al comprar",formaYa:"Forma al comprar",segYa:"Seguidores al comprar",misterYa:"Míster al comprar",afinYa:"Afinidad al comprar",egoYa:"Ego al comprar",misterSem:"Míster por semana",amortMister:"Amortigua al míster",vicioMod:"Tentación de vicio",vicioTent:"Tentación de vicio",duelo:"Duelo ×",pase:"Pase ×",salida:"Salida ×",penal:"Penalti ×",fis:"Físico ×",tarjeta:"Tarjeta ×",recupera:"Recupera ×",desgaste:"Desgaste ×",riesgo:"Riesgo ×",TEC:"Técnica",FIS:"Físico",TAC:"Táctica",DEF:"Defensa",MEN:"Mentalidad",POR:"Portería"};
function fxEd(pre,fx,R,full){
  R=R||{}; var out=[], used={};
  function walk(o,pp,rr,sub){ Object.keys(o||{}).forEach(function(k){ var v=o[k];
    if(v && typeof v==="object" && !Array.isArray(v)){ walk(v,pp+"."+k,(k==="inst"?G.CONT_R.inst:(k==="mult"?G.CONT_R.tent:rr)),k==="inst"?"prob. ":k==="mult"?"entreno ":k+" "); return; }
    if(typeof v!=="number"){ if(typeof v==="boolean") out.push('<span class="fxi">'+(FXN[k]||k)+' <b style="padding:0 6px">'+(v?"sí":"no")+'</b></span>'); return; }
    var p=pp+"."+k, r=rr&&rr[k]; reg(p,v,full+" · "+(sub||"")+(FXN[k]||k)); used[k]=1; if(val(p)===null) return;
    out.push('<span class="fxi'+(chg(p)?" chg":"")+'" title="'+(r?"rango "+r[0]+" – "+r[1]:"")+(chg(p)?" · fábrica "+BASE[p]:"")+'">'+(sub||"")+(FXN[k]||k)+'<input type="number" step="any" value="'+val(p)+'" onchange="'+on(function(x){ x=Number(x); if(r) x=clamp(x,r[0],r[1]); set(p,x); })+'">'+(chg(p)?'<u title="deshacer" onclick="'+on(function(){set(p,BASE[p])})+'">↺</u>':'')+'</span>'); }); }
  walk(fx,pre,R,"");
  var libres=Object.keys(R).filter(function(k){return !used[k]});
  return '<div class="fx">'+out.join("")+(libres.length?'<select onchange="'+on(function(x,el){ el.selectedIndex=0; toast("Añade el efecto «"+x+"» con su rango"); })+'"><option>+ efecto</option>'+libres.map(function(k){return '<option>'+(FXN[k]||k)+'</option>'}).join("")+'</select>':'')+'</div>';
}
function fn(v,nota){ return '<div class="code">'+esc(v.$fn)+'</div><div class="small mut" style="margin-top:4px">'+(nota||"Fórmula escrita en el código del juego. No se edita desde el panel.")+'</div>'; }

