function priLeer(){
  try{ var r=localStorage.getItem(PRI_KEY); if(r){ var a=JSON.parse(r); if(Array.isArray(a)) return a; } }catch(e){}
  return PRI_SEMILLA.map(function(x,i){ return {id:"s"+i, p:x[0], area:x[1], est:x[2], title:x[3], note:x[4]||"", adm:x[5]||"", done:false, ts:i}; });
}
function priGuardar(a){ try{ localStorage.setItem(PRI_KEY, JSON.stringify(a)); }catch(e){ toast("No se pudo guardar en este navegador"); } }
function priCambia(id, f){ var a=priLeer(); a.forEach(function(x){ if(x.id===id) f(x); }); priGuardar(a); go(); }
function priMover(id, d){ priCambia(id, function(x){ x.p=Math.max(0, Math.min(5, x.p+d)); }); }
function priHecho(id){ priCambia(id, function(x){ x.done=!x.done; }); }
function priDel(id){
  if(ST.sel.prDel!==id){ ST.sel.prDel=id; go(); return; }
  priGuardar(priLeer().filter(function(x){ return x.id!==id; })); ST.sel.prDel=null; go();
}
function priNuevo(){ ST.sel.prNew=true; ST.sel.prEdit=null; ST.sel.prDel=null; go(); }
function priEdit(id){ ST.sel.prEdit=id; ST.sel.prNew=null; ST.sel.prDel=null; go(); }
function priCancel(){ ST.sel.prNew=null; ST.sel.prEdit=null; go(); }
function priGuardarForm(id){
  var g=function(k){ return document.getElementById(k).value; };
  var t=(g("pri-tit")||"").trim(); if(!t){ toast("Escribe un título"); return; }
  var d={ p:+g("pri-p"), area:g("pri-area"), est:g("pri-est"), adm:g("pri-adm"), title:t, note:(g("pri-not")||"").trim() };
  var a=priLeer();
  if(id) a.forEach(function(x){ if(x.id===id){ x.p=d.p; x.area=d.area; x.est=d.est; x.adm=d.adm; x.title=d.title; x.note=d.note; } });
  else a.push({id:Date.now().toString(36)+Math.random().toString(36).slice(2,6), p:d.p, area:d.area, est:d.est, adm:d.adm, title:d.title, note:d.note, done:false, ts:Date.now()});
  priGuardar(a); ST.sel.prNew=null; ST.sel.prEdit=null; go();
}
function priRestaurar(){
  if(ST.sel.prRes!==1){ ST.sel.prRes=1; go(); return; }
  try{ localStorage.removeItem(PRI_KEY); }catch(e){} ST.sel.prRes=null; go();
}
function priAdmTxt(v){ return v===""? "Sin apartado en admin" : (v==="—"? "No aplica" : "Admin · "+v); }
function priCopiar(){
  var a=priLeer().filter(function(x){ return !x.done; }), txt=[];
  PRI_AREAS.forEach(function(ar){
    var l=a.filter(function(x){ return x.area===ar; }).sort(function(x,y){ return (x.p-y.p) || (x.ts-y.ts); });
    if(!l.length) return;
    txt.push("## "+ar);
    l.forEach(function(x){ txt.push("- [P"+x.p+" · "+x.est+" · "+priAdmTxt(x.adm)+"] "+x.title+(x.note? " — "+x.note : "")); });
    txt.push("");
  });
  try{ navigator.clipboard.writeText(txt.join("\n").trim()).then(function(){ toast("Inventario copiado"); }, function(){ toast("No se pudo copiar"); }); }
  catch(e){ toast("No se pudo copiar"); }
}
function priForm(){
  var item=null, CSS="width:100%;background:var(--card2);color:var(--ink);border:1px solid var(--line);border-radius:8px;padding:8px 10px;font:inherit";
  if(ST.sel.prEdit){ priLeer().forEach(function(x){ if(x.id===ST.sel.prEdit) item=x; }); if(!item) return ""; }
  if(!ST.sel.prNew && !item) return "";
  var p=item? item.p : 2, area=item? item.area : "Partidos", est=item? item.est : "Funciona, mejorable", adm=item? item.adm : "";
  var sel=function(id, ops, cur){ return '<select id="'+id+'" style="'+CSS+'">'+ops.map(function(x){ return '<option'+(x===cur?" selected":"")+'>'+esc(x)+'</option>'; }).join("")+'</select>'; };
  var fila=function(l, c){ return '<div class="f"><label>'+l+'</label><div style="flex:1 1 260px">'+c+'</div></div>'; };
  var admOps='<option value=""'+(adm===""?" selected":"")+'>Sin apartado en admin</option><option value="—"'+(adm==="—"?" selected":"")+'>No aplica</option>'
    +NAV.map(function(g){ return g[1].map(function(i){ return '<option'+(i[2]===adm?" selected":"")+'>'+esc(i[2])+'</option>'; }).join(""); }).join("");
  return '<div class="card" style="border-color:var(--acc)"><h3>'+(item?"Editar pieza":"Nueva pieza")+'</h3>'
    +fila("Prioridad",'<select id="pri-p" style="'+CSS+'">'+PRI_NIV.map(function(n,i){ return '<option value="'+i+'"'+(i===p?" selected":"")+'>'+n[0]+' · '+esc(n[1])+'</option>'; }).join("")+'</select>')
    +fila("Área del juego", sel("pri-area",PRI_AREAS,area))
    +fila("Estado", sel("pri-est",PRI_ESTADOS,est))
    +fila("Apartado en admin",'<select id="pri-adm" style="'+CSS+'">'+admOps+'</select>')
    +fila("Pieza",'<input id="pri-tit" value="'+esc(item?item.title:"")+'" style="'+CSS+'">')
    +fila("Qué hay hoy",'<textarea id="pri-not" rows="3" style="'+CSS+'">'+esc(item?item.note:"")+'</textarea>')
    +'<div style="display:flex;justify-content:flex-end;gap:8px;margin-top:10px">'
    +'<button class="b" onclick="priCancel()">Cancelar</button>'
    +'<button class="b gold" onclick="priGuardarForm('+(item? "'"+item.id+"'" : "null")+')">Guardar</button></div></div>';
}
V.prioridades=function(){
  var tb=tabs("pr",["Pendientes","Sin apartado en admin","Rediseñados"]), tab=ST.tab.pr||"Pendientes";
  var ta=tabs("pra",["Todas las áreas"].concat(PRI_AREAS)), area=ST.tab.pra||"Todas las áreas";
  var a=priLeer(), pend=a.filter(function(x){return !x.done;}).length;
  var sinAdm=a.filter(function(x){ return !x.done && x.adm===""; }).length;
  var ve=function(x){
    if(area!=="Todas las áreas" && x.area!==area) return false;
    if(tab==="Rediseñados") return x.done;
    if(x.done) return false;
    if(tab==="Sin apartado en admin") return x.adm==="";
    return true;
  };
  var resumen=PRI_ESTADOS.map(function(e){ var n=a.filter(function(x){ return !x.done && x.est===e; }).length; return n? '<span style="white-space:nowrap"><b style="color:'+PRI_ECOL[e]+'">'+n+'</b> '+esc(e.toLowerCase())+'</span>' : ""; }).filter(Boolean).join(" · ");
  var cuerpo=PRI_NIV.map(function(n,i){
    var l=a.filter(function(x){ return x.p===i && ve(x); }).sort(function(x,y){ return (PRI_AREAS.indexOf(x.area)-PRI_AREAS.indexOf(y.area)) || (x.ts-y.ts); });
    var filas=l.map(function(x){
      var admTag= x.adm===""? '<span class="tag" style="color:#ff5470;border-color:#ff5470">Sin apartado en admin</span>'
        : (x.adm==="—"? '<span class="tag">No aplica al admin</span>' : '<span class="tag">Admin · '+esc(x.adm)+'</span>');
      return '<div class="pri-row" style="display:flex;gap:10px;align-items:flex-start;padding:9px 0;border-bottom:1px solid var(--line);flex-wrap:wrap">'
        +'<div style="flex:1 1 320px;min-width:0;'+(x.done?'opacity:.55':'')+'"><b>'+esc(x.title)+'</b>'
        +'<div style="display:flex;gap:6px;flex-wrap:wrap;margin:4px 0 2px"><span class="tag">'+esc(x.area||"")+'</span>'
        +'<span class="tag" style="color:'+(PRI_ECOL[x.est]||"inherit")+';border-color:'+(PRI_ECOL[x.est]||"var(--line)")+'">'+esc(x.est||"")+'</span>'+admTag+'</div>'
        +(x.note? '<div class="mut" style="font-size:12px;margin-top:2px;white-space:pre-wrap">'+esc(x.note)+'</div>' : '')+'</div>'
        +'<div style="display:flex;gap:6px;flex:none;flex-wrap:wrap;justify-content:flex-end">'
        +'<button class="b sm" title="Más prioridad" onclick="priMover(\''+x.id+'\',-1)"'+(x.p<=0?' disabled':'')+'>▲</button>'
        +'<button class="b sm" title="Menos prioridad" onclick="priMover(\''+x.id+'\',1)"'+(x.p>=5?' disabled':'')+'>▼</button>'
        +'<button class="b sm" onclick="priEdit(\''+x.id+'\')">Editar</button>'
        +'<button class="b sm" onclick="priHecho(\''+x.id+'\')">'+(x.done?"Reabrir":"Rediseñado")+'</button>'
        +'<button class="b sm red" onclick="priDel(\''+x.id+'\')">'+(ST.sel.prDel===x.id?"¿Borrar?":"Borrar")+'</button>'
        +'</div></div>';
    }).join("");
    return '<div style="margin-top:16px"><div style="display:flex;align-items:baseline;gap:10px;padding-bottom:6px;border-bottom:2px solid '+n[2]+'">'
      +'<b class="pri-niv" style="color:'+n[2]+';font-size:15px">'+n[0]+'</b><span class="mut" style="font-size:12px;flex:1">'+esc(n[1])+'</span>'
      +'<span class="mut" style="font-size:12px">'+l.length+'</span></div>'
      +(filas || '<div class="mut" style="font-size:12px;padding:8px 0">Nada en este nivel.</div>')+'</div>';
  }).join("");
  return hd("Prioridades","Inventario del juego y del admin, agrupado por áreas del juego (partidos, decisiones, entrenamientos, talentos, agentes…). Cada pieza tiene prioridad (P0 a P5), estado y su apartado en el admin. Se guarda solo en este navegador.")
    +'<div class="card"><h3>Inventario <span class="mut" style="font-weight:400">('+pend+' piezas por rediseñar · '+sinAdm+' sin apartado en el admin · '+(a.length-pend)+' rediseñadas)</span></h3>'
    +'<p class="mut" style="font-size:12px;margin:0 0 10px">'+resumen+'</p>'
    +tb+ta+priForm()+cuerpo
    +'<div style="display:flex;flex-wrap:wrap;gap:8px;margin-top:16px;padding-top:12px;border-top:1px solid var(--line)">'
    +'<button class="b gold" style="flex:1 1 40%" onclick="priNuevo()">+ Pieza</button>'
    +'<button class="b" style="flex:1 1 25%" onclick="priCopiar()">Copiar inventario…</button>'
    +'<button class="b" style="flex:1 1 25%" onclick="priRestaurar()">'+(ST.sel.prRes===1?"¿Seguro? Se pierden tus cambios":"Volver a la propuesta inicial")+'</button>'
    +'</div></div>';
};

/* ===== TRACKER · features, bugs y mejoras (se guarda solo en este navegador, no se sube a ningún sitio) ===== */
var TRK_KEY="admin-tracker-v1";
var TRK_TIPO={feat:"Feature", bug:"Bug", imp:"Mejora"};
var TRK_CLS={feat:"", bug:"", imp:""};
function trkLeer(){ try{ var a=JSON.parse(localStorage.getItem(TRK_KEY)||"[]"); return Array.isArray(a)?a:[]; }catch(e){ return []; } }
function trkGuardar(a){ try{ localStorage.setItem(TRK_KEY, JSON.stringify(a)); }catch(e){ toast("No se pudo guardar en este navegador"); } }
function trkNuevo(t){ ST.sel.trNew=t; ST.sel.trEdit=null; ST.sel.trDel=null; go(); }
function trkEdit(id){ ST.sel.trEdit=id; ST.sel.trNew=null; ST.sel.trDel=null; go(); }
function trkCancel(){ ST.sel.trNew=null; ST.sel.trEdit=null; go(); }
function trkLeerForm(){
  return { title:(document.getElementById("trk-tit").value||"").trim(), note:(document.getElementById("trk-not").value||"").trim() };
}
function trkGuardarNuevo(){
  var f=trkLeerForm(); if(!f.title){ toast("Escribe un título"); return; }
  var a=trkLeer();
  a.push({id:Date.now().toString(36)+Math.random().toString(36).slice(2,6), t:ST.sel.trNew, title:f.title, note:f.note, arch:false, ts:Date.now()});
  trkGuardar(a); ST.sel.trNew=null; go();
}
function trkGuardarEdit(id){
  var f=trkLeerForm(); if(!f.title){ toast("Escribe un título"); return; }
  var a=trkLeer(); a.forEach(function(x){ if(x.id===id){ x.title=f.title; x.note=f.note; } });
  trkGuardar(a); ST.sel.trEdit=null; go();
}
function trkArch(id){
  var a=trkLeer(); a.forEach(function(x){ if(x.id===id) x.arch=!x.arch; });
  trkGuardar(a); go();
}
function trkDel(id){
  if(ST.sel.trDel!==id){ ST.sel.trDel=id; go(); return; }   /* primer clic: pide confirmar */
  trkGuardar(trkLeer().filter(function(x){ return x.id!==id; }));
  ST.sel.trDel=null; go();
}
function trkOk(x, tab){
  if(tab==="Archivados") return x.arch;
  if(x.arch) return false;
  if(tab==="Features") return x.t==="feat";
  if(tab==="Bugs") return x.t==="bug";
  if(tab==="Mejoras") return x.t==="imp";
  return true;
}
function trkFiltra(q){
  q=String(q||"").toLowerCase().trim();
  var filas=document.querySelectorAll(".trk-row");
  for(var i=0;i<filas.length;i++){
    var r=filas[i], ok=r.getAttribute("data-ok")==="1" && (!q || r.getAttribute("data-q").indexOf(q)>=0);
    r.style.display= ok? "" : "none";
  }
}
function trkCopiar(){
  var a=trkLeer().filter(function(x){ return !x.arch; }), txt=[];
  ["feat","bug","imp"].forEach(function(t){
    var l=a.filter(function(x){ return x.t===t; });
    if(!l.length) return;
    txt.push("## "+TRK_TIPO[t]+"s");
    l.forEach(function(x){ txt.push("- "+x.title+(x.note? " — "+x.note : "")); });
    txt.push("");
  });
  var t=txt.join("\n").trim() || "Nada pendiente.";
  try{ navigator.clipboard.writeText(t).then(function(){ toast("Copiado al portapapeles"); }, function(){ toast("No se pudo copiar"); }); }
  catch(e){ toast("No se pudo copiar"); }
}
function trkForm(){
  var nuevo=ST.sel.trNew, edit=ST.sel.trEdit, item=null;
  if(edit){ trkLeer().forEach(function(x){ if(x.id===edit) item=x; }); if(!item) return ""; }
  if(!nuevo && !item) return "";
  var t=item? item.t : nuevo;
  return '<div class="card" style="border-color:var(--acc)"><h3>'+(item?"Editar":"Nuevo")+' · '+TRK_TIPO[t]+'</h3>'
    +'<div class="f"><label>Título</label><div style="flex:1 1 260px"><input id="trk-tit" value="'+esc(item?item.title:"")+'" style="width:100%;background:var(--card2);color:var(--ink);border:1px solid var(--line);border-radius:8px;padding:8px 10px;font:inherit"></div></div>'
    +'<div class="f"><label>Notas</label><div style="flex:1 1 260px"><textarea id="trk-not" rows="3" style="width:100%;background:var(--card2);color:var(--ink);border:1px solid var(--line);border-radius:8px;padding:8px 10px;font:inherit">'+esc(item?item.note:"")+'</textarea></div></div>'
    +'<div style="display:flex;justify-content:flex-end;gap:8px;margin-top:10px">'
    +'<button class="b" onclick="trkCancel()">Cancelar</button>'
    +'<button class="b gold" onclick="'+(item? "trkGuardarEdit('"+item.id+"')" : "trkGuardarNuevo()")+'">Guardar</button></div></div>';
}
V.tracker=function(){
  var tb=tabs("tr",["Todos","Features","Bugs","Mejoras","Archivados"]);
  var a=trkLeer(), activos=a.filter(function(x){return !x.arch;}).length, archivados=a.length-activos;
  var tab=ST.tab.tr||"Todos";
  var orden=a.slice().sort(function(x,y){ return (x.arch-y.arch) || (y.ts-x.ts); });
  var filas=orden.map(function(x){
    var ok=trkOk(x, tab), borrar=ST.sel.trDel===x.id;
    return '<div class="trk-row" data-ok="'+(ok?1:0)+'" data-q="'+esc((x.title+" "+x.note).toLowerCase())+'" style="display:'+(ok?"flex":"none")+';gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--line)">'
      +'<span class="tag" style="flex:none;margin-top:2px">'+TRK_TIPO[x.t]+'</span>'
      +'<div style="flex:1;min-width:0;'+(x.arch?'opacity:.55;text-decoration:line-through':'')+'"><b>'+esc(x.title)+'</b>'
      +(x.note? '<div class="mut" style="font-size:12px;margin-top:2px;white-space:pre-wrap">'+esc(x.note)+'</div>' : '')+'</div>'
      +'<div style="display:flex;gap:6px;flex:none">'
      +'<button class="b sm" onclick="trkEdit(\''+x.id+'\')">Editar</button>'
      +'<button class="b sm" onclick="trkArch(\''+x.id+'\')">'+(x.arch?"Restaurar":"Archivar")+'</button>'
      +'<button class="b sm red" onclick="trkDel(\''+x.id+'\')">'+(borrar?"¿Borrar?":"Borrar")+'</button>'
      +'</div></div>';
  }).join("");
  var vacio = a.length? "" : '<p class="mut" style="text-align:center;padding:30px 0">Sin nada apuntado. Usa los botones de abajo.</p>';
  return hd("Tracker","Lo que hay que hacer en el juego: features, bugs y mejoras. Se guarda solo en este navegador.")
    +'<div class="card"><h3>Tracker <span class="mut" style="font-weight:400">('+activos+' activos · '+archivados+' archivados)</span></h3>'
    +'<div style="margin-bottom:10px"><input placeholder="Buscar…" oninput="trkFiltra(this.value)" style="width:100%;background:var(--card2);color:var(--ink);border:1px solid var(--line);border-radius:8px;padding:8px 10px;font:inherit"></div>'
    +tb
    +trkForm()
    +'<div style="margin-top:6px">'+filas+'</div>'+vacio
    +'<div style="display:flex;flex-wrap:wrap;gap:8px;margin-top:14px;padding-top:12px;border-top:1px solid var(--line)">'
    +'<button class="b" style="flex:1 1 100%" onclick="trkCopiar()">Copiar lista…</button>'
    +'<button class="b gold" style="flex:1 1 30%" onclick="trkNuevo(\'feat\')">+ Feat</button>'
    +'<button class="b gold" style="flex:1 1 30%" onclick="trkNuevo(\'bug\')">+ Bug</button>'
    +'<button class="b gold" style="flex:1 1 30%" onclick="trkNuevo(\'imp\')">+ Imp</button>'
    +'</div></div>';
};

