function nextIter(v){ var p=String(v).split("."); return p.length===3? p[0]+"."+p[1]+"."+String(+p[2]+1).padStart(3,"0") : v; }
function publicarLocal(){ var n=$("nota"); if(!n || !n.value.trim()){ toast("Escribe la nota de la versión"); return; } ST.ver=nextIter(ST.ver); CUR_VER=ST.ver; CUR_VER_DATE=new Date().toISOString(); pintaVers(); VERS.unshift([ST.ver,"ahora",n.value,nCam()]); Object.keys(DRAFT).forEach(function(p){ BASE[p]=DRAFT[p]; }); DRAFT={}; try{ localStorage.removeItem(BORR_KEY); }catch(e){} go(); toast("Publicada la versión "+ST.ver); }
/* los ajustes de partido llegan al juego: se publica una versión nueva de tl_content partiendo de la última
   publicada (así no se pierde lo que ya haya publicado el admin antiguo) y solo cambia el bloque «partido» */
/* el borrador de situaciones, en el mismo formato que el bloque «sits» del juego */
function sitsDesdeBorrador(){
  var out={};
  Object.keys(DRAFT).forEach(function(p){
    var m=p.match(/^si\.[jbck]\.([^.]+)\.(.+)$/); if(!m) return;
    var id=m[1], parts=m[2].split("."), o=out[id]||(out[id]={}), cur=o;
    if(/^o\d+$/.test(parts[0])){ cur.o=cur.o||{}; cur.o[parts[0].slice(1)]=cur.o[parts[0].slice(1)]||{}; cur=cur.o[parts[0].slice(1)]; parts.shift(); }
    while(parts.length>1){ cur[parts[0]]=cur[parts[0]]||{}; cur=cur[parts[0]]; parts.shift(); }
    cur[parts[0]]=DRAFT[p];
    out[id]=o;
  });
  return out;
}
function mezclaProfunda(a,b){
  Object.keys(b).forEach(function(k){
    var v=b[k];
    if(v && typeof v==="object" && !Array.isArray(v)) a[k]=mezclaProfunda(a[k]&&typeof a[k]==="object"&&!Array.isArray(a[k])? a[k] : {}, v);
    else a[k]=v;
  });
  return a;
}
function pbPublicaPartido(nota){
  var mn=val("pj.min"), mx=val("pj.max");
  return pbApi("/api/collections/tl_content/records?perPage=1&sort=-n&filter="+encodeURIComponent("(kind='ver')")).then(function(r){
    var last=r.items&&r.items[0];
    var pack=(last&&last.pack)? JSON.parse(JSON.stringify(last.pack)) : {v:1};
    pack.v=1; pack.partido={min:mn,max:mx,previa:val("pj.previa"),post:val("pj.post")};
    var cambiosSits=sitsDesdeBorrador(); if(Object.keys(cambiosSits).length) pack.sits=mezclaProfunda(pack.sits||{}, cambiosSits);
    return pbApi("/api/collections/tl_content/records",{method:"POST",headers:PB_JSON,body:JSON.stringify({kind:"ver",n:(last?last.n:0)+1,pack:pack,nota:nota,t:Date.now(),ver_juego:nextIter(ST.ver)})});
  });
}
function publicar(){
  var n=$("nota"); if(!n || !n.value.trim()){ toast("Escribe la nota de la versión"); return; }
  var pj=Object.keys(DRAFT).some(function(p){ return p.indexOf("pj.")===0 || /^si\.[jbck]\./.test(p); });
  if(!pj) return publicarLocal();
  if(val("pj.min")>val("pj.max")){ toast("El máximo de situaciones no puede ser menor que el mínimo"); return; }
  pbPublicaPartido(n.value.trim()).then(function(){ publicarLocal(); toast("Publicado en el juego"); },
    function(e){ toast("No se publicó en el juego: "+(e.message||e)); });
}
