/* categorías de las situaciones, solo para organizar el panel (no cambian nada del juego) */

/* ---- situaciones: exportar, importar y guardar ----
   Formato = bloque «sits» del paquete de contenido del juego: {v:1, sits:{id:{t,x,pos,off,o:{i:{l,ok,mid,ko,fx}}}}}.
   Importar no toca nada hasta pulsar Guardar; Guardar valida todo antes de aplicar (si hay un error, no aplica nada).
   Guardar deja los cambios en el borrador; Publicar los manda al juego. */
OK_BTN.push("Copiar esta","Copiar todas","Importar","Pegar del portapapeles","Revisar","Guardar","Cerrar importación","+ condición");
/* «Cuándo sale»: reglas que se suman a la condición del código. Mismo formato que el juego. */
var COND_PROPS=[["min","Minuto","num"],["dif","Diferencia de goles (tú − rival)","num"],["goles","Tus goles","num"],["casa","Juegas en casa","bool"],["marcador","Marcador ahora","txt",["ganas","empatas","pierdes"],["vas ganando","empatas","vas perdiendo"]],["azar","Probabilidad (%)","pct"]];
var COND_OPS=[">=","<=",">","<","="];
function condErr(L){
  if(!Array.isArray(L)) return "no es una lista";
  for(var i=0;i<L.length;i++){ var r=L[i], d=COND_PROPS.filter(function(q){ return q[0]===r.p; })[0];
    if(!d) return "regla "+(i+1)+": propiedad no válida";
    if(d[2]==="num" && (COND_OPS.indexOf(r.op)<0 || typeof r.v!=="number")) return "regla "+(i+1)+": operador o número no válido";
    if(d[2]==="bool" && typeof r.v!=="boolean") return "regla "+(i+1)+": debe ser sí o no";
    if(d[2]==="txt" && d[3].indexOf(r.v)<0) return "regla "+(i+1)+": valor no válido";
    if(d[2]==="pct" && (typeof r.v!=="number"||r.v<1||r.v>100)) return "regla "+(i+1)+": porcentaje entre 1 y 100"; }
  return null; }
function condEditor(pre,x){
  reg(pre+".cuando",[],"Cuándo sale · reglas extra");
  var L=val(pre+".cuando")||[];
  var up=function(c2){ set(pre+".cuando", c2); };
  var filas=L.map(function(r,i){
    var d=COND_PROPS.filter(function(q){ return q[0]===r.p; })[0]||COND_PROPS[0], valor="";
    var sel='<select onchange="'+on(function(v){ var d2=COND_PROPS.filter(function(q){ return q[0]===v; })[0]; var nr=d2[2]==="num"?{p:v,op:">=",v:0}:d2[2]==="bool"?{p:v,v:true}:d2[2]==="txt"?{p:v,v:d2[3][0]}:{p:v,v:50}; var c2=L.slice(); c2[i]=nr; up(c2); })+'">'
      +COND_PROPS.map(function(q){ return '<option value="'+q[0]+'"'+(q[0]===r.p?' selected':'')+'>'+esc(q[1])+'</option>'; }).join("")+'</select>';
    var setV=function(nr){ var c2=L.slice(); c2[i]=nr; up(c2); };
    if(d[2]==="num") valor='<select onchange="'+on(function(v){ setV(Object.assign({},r,{op:v})); })+'">'+COND_OPS.map(function(o){ return '<option'+(o===r.op?' selected':'')+'>'+o+'</option>'; }).join("")+'</select>'
      +' <input type="number" step="1" value="'+r.v+'" style="width:70px" onchange="'+on(function(v){ setV(Object.assign({},r,{v:Number(v)})); })+'">';
    else if(d[2]==="bool") valor='<select onchange="'+on(function(v){ setV(Object.assign({},r,{v:v==="sí"})); })+'">'+["sí","no"].map(function(o){ return '<option'+((r.v?"sí":"no")===o?' selected':'')+'>'+o+'</option>'; }).join("")+'</select>';
    else if(d[2]==="txt") valor='<select onchange="'+on(function(v){ setV(Object.assign({},r,{v:v})); })+'">'+d[3].map(function(o,k){ return '<option value="'+o+'"'+(o===r.v?' selected':'')+'>'+d[4][k]+'</option>'; }).join("")+'</select>';
    else valor='<input type="number" min="1" max="100" value="'+r.v+'" style="width:70px" onchange="'+on(function(v){ setV(Object.assign({},r,{v:Number(v)})); })+'"> %';
    return '<div class="row" style="gap:6px;margin-bottom:6px;flex-wrap:wrap">'+sel+valor+'<span class="sp"></span>'+btn("✕",function(){ var c2=L.slice(); c2.splice(i,1); up(c2); },"sm")+'</div>'; }).join("");
  return '<div class="f"><label>Cuándo sale</label><div>'
    +(x.cond? '<p class="small mut" style="margin:0 0 8px">Además sale solo si se cumple su condición fija del código (no se edita). <details style="display:inline"><summary style="cursor:pointer">ver código</summary><div class="code" style="margin-top:6px">'+esc(String(x.cond).replace(/^function\s*\([^)]*\)\s*\{\s*return\s*/,"").replace(/;\s*\}\s*$/,""))+'</div></details></p>':'')
    +(filas || '<p class="small mut" style="margin:0 0 8px">Sin reglas extra: sale según el código.</p>')
    +btn("+ condición",function(){ up(L.concat([{p:"min",op:">=",v:20}])); },"sm")
    +'</div><div class="fab"></div></div>'; }

function sitLista(){ var out=[]; [["si.j",G.SITS],["si.b",G.SITS_BANQUILLO],["si.c",G.SITS_CAMBIO],["si.k",G.SITS_CLUTCH]].forEach(function(g){ g[1].forEach(function(x){ out.push({x:x,pre:g[0]}); }); }); return out; }
function vv(p,fab){ reg(p,fab,"Situación · "+p.split(".").slice(2).join(".")); return val(p); }
function sitFxLeer(base,fx){ var out={}; Object.keys(fx||{}).forEach(function(k){ var v=fx[k], p=base+"."+k;
  if(v && typeof v==="object" && !Array.isArray(v)){ out[k]=sitFxLeer(p,v); return; }
  if(typeof v==="number"||typeof v==="boolean") out[k]=vv(p,v); }); return out; }
function sitObj(e){ var x=e.x, pre=e.pre+"."+x.id, o={};
  if(!isFn(x.t)) o.t=vv(pre+".t",x.t);
  if(!isFn(x.x)) o.x=vv(pre+".x",x.x);
  o.pos=vv(pre+".pos",x.pos||null);
  o.off=vv(pre+".off",false);
  var cu=vv(pre+".cuando",[]); if(cu && cu.length) o.cuando=JSON.parse(JSON.stringify(cu));
  o.o={};
  x.o.forEach(function(op,i){ var po=pre+".o"+i, r={};
    if(!isFn(op.l)) r.l=vv(po+".l",op.l);
    ["ok","mid","ko"].forEach(function(k){ if(typeof op[k]==="string") r[k]=vv(po+"."+k,op[k]); });
    r.fx=sitFxLeer(po+".fx",op.fx||{});
    o.o[i]=r; });
  return o; }
function sitExportar(lista){ var S2={}; lista.forEach(function(e){ S2[e.x.id]=sitObj(e); }); return JSON.stringify({v:1,sits:S2},null,2); }
function sitCopiar(todas){
  var lista=sitLista(), txt;
  if(todas) txt=sitExportar(lista);
  else { var sel=lista.filter(function(e){ return e.x.id===(ST.sel.si||"por-salida"); })[0]; if(!sel){ toast("No hay situación seleccionada"); return; } txt=sitExportar([sel]); }
  ST.sel.impTxt=txt; ST.tab.imp=true; ST.sel.impRes=null;
  if(navigator.clipboard && navigator.clipboard.writeText){ navigator.clipboard.writeText(txt).then(function(){ toast(todas? "Copiadas todas las situaciones":"Situación copiada"); }, function(){ toast("No se pudo copiar: está en el cuadro de importar"); }); }
  else toast("Copia el texto del cuadro de importar");
  go(); }
function sitFxAplicar(base,nuevo,fab,put,err){
  Object.keys(nuevo).forEach(function(k){ var v=nuevo[k], p=base+"."+k;
    if(!fab || !fab.hasOwnProperty(k)){ err("efecto desconocido «"+k+"»"); return; }
    if(v && typeof v==="object" && !Array.isArray(v)){ sitFxAplicar(p,v,fab[k],put,err); return; }
    if(typeof fab[k]!=="number" || typeof v!=="number"){ err("«"+k+"» debe ser un número"); return; }
    put(p,v); }); }
function sitRevisar(txt){
  var P; try{ P=JSON.parse(txt); }catch(e){ return {err:"No es JSON válido ("+e.message+")."}; }
  if(!P || typeof P!=="object" || !P.sits || typeof P.sits!=="object" || Array.isArray(P.sits)) return {err:"Falta el bloque «sits». Usa el formato de Copiar."};
  var byId={}; sitLista().forEach(function(e){ byId[e.x.id]=e; });
  var cambios=[], errores=[], tocadas={};
  Object.keys(P.sits).forEach(function(id){
    var s2=P.sits[id], e=byId[id];
    if(!e){ errores.push(id+": esa situación no existe"); return; }
    if(!s2 || typeof s2!=="object"){ errores.push(id+": no es un objeto"); return; }
    sitObj(e);   /* registra los valores de fábrica de esta situación para comparar */
    var pre=e.pre+"."+id, n0=cambios.length, x=e.x;
    var err=function(m){ errores.push(id+": "+m); };
    var put=function(p,v){ if(!same(val(p),v)) cambios.push([p,v]); };
    if(s2.t!==undefined){ if(isFn(x.t)) err("el título lo calcula el juego"); else if(typeof s2.t!=="string"||!s2.t.trim()) err("título vacío o no es texto"); else put(pre+".t",s2.t.trim()); }
    if(s2.x!==undefined){ if(isFn(x.x)) err("el texto lo calcula el juego"); else if(typeof s2.x!=="string"||!s2.x.trim()) err("texto vacío o no es texto"); else put(pre+".x",s2.x.trim()); }
    if(s2.pos!==undefined){ if(s2.pos!==null && (!Array.isArray(s2.pos)||!s2.pos.length||s2.pos.some(function(q){ return POSS.indexOf(q)<0; }))) err("puestos no válidos"); else put(pre+".pos",s2.pos); }
    if(s2.off!==undefined){ if(typeof s2.off!=="boolean") err("off debe ser sí/no"); else put(pre+".off",s2.off); }
    if(s2.cuando!==undefined){ var ce=condErr(s2.cuando); if(ce) err("cuando: "+ce); else put(pre+".cuando",s2.cuando); }
    if(s2.o!==undefined){ if(!s2.o||typeof s2.o!=="object"||Array.isArray(s2.o)) err("o no es un objeto");
      else Object.keys(s2.o).forEach(function(i){
        var op=x.o[+i], r=s2.o[i], po=pre+".o"+i;
        if(!op){ err("la opción "+i+" no existe"); return; }
        if(!r||typeof r!=="object"){ err("opción "+i+" no es un objeto"); return; }
        if(r.l!==undefined){ if(isFn(op.l)) err("botón "+i+" lo calcula el juego"); else if(typeof r.l!=="string"||!r.l.trim()) err("botón "+i+" vacío"); else put(po+".l",r.l.trim()); }
        ["ok","mid","ko"].forEach(function(k){ if(r[k]===undefined) return; if(typeof op[k]!=="string" && op[k]!==undefined) return err("«"+k+"» de la opción "+i+" lo calcula el juego"); if(typeof r[k]!=="string") return err("«"+k+"» de la opción "+i+" no es texto"); put(po+"."+k,r[k]); });
        if(r.fx!==undefined){ if(!r.fx||typeof r.fx!=="object"||Array.isArray(r.fx)) err("fx de la opción "+i+" no es un objeto"); else sitFxAplicar(po+".fx",r.fx,op.fx||{},put,function(m){ err("opción "+i+": "+m); }); }
      }); }
    if(cambios.length>n0) tocadas[id]=1;
  });
  return {cambios:cambios, errores:errores, tocadas:Object.keys(tocadas).length};
}
function sitGuardar(){
  var r=sitRevisar(ST.sel.impTxt||"");
  ST.sel.impRes=r;
  if(r.err){ toast(r.err); go(); return; }
  if(r.errores.length){ toast("Hay "+r.errores.length+" error(es). No se ha guardado nada."); go(); return; }
  if(!r.cambios.length){ toast("No hay cambios que guardar"); go(); return; }
  r.cambios.forEach(function(c){ var p=c[0], v=c[1]; if(same(v,BASE[p])) delete DRAFT[p]; else DRAFT[p]=v; });
  topbar(); toast("Guardado en borrador: "+r.cambios.length+" cambio(s). Publica para llevarlo al juego.");
  ST.tab.imp=false; go(); }
function importCard(){
  var res=ST.sel.impRes, txt=ST.sel.impTxt||"";
  var resumen="";
  if(res){ if(res.err) resumen='<p class="err small" style="margin:8px 0 0">'+esc(res.err)+'</p>';
    else { resumen= res.errores.length? '<p class="small" style="margin:8px 0 0"><span class="err"><b>'+res.errores.length+'</b> error(es): no se guardará nada.</span></p>' : '<p class="small" style="margin:8px 0 0"><b>'+res.tocadas+'</b> situación(es) con <b>'+res.cambios.length+'</b> cambio(s) listos para guardar.</p>';
      if(res.errores.length) resumen+='<ul class="small err" style="margin:6px 0 0 16px">'+res.errores.slice(0,8).map(function(m){ return '<li>'+esc(m)+'</li>'; }).join("")+'</ul>';
      if(res.cambios.length && !res.errores.length) resumen+='<ul class="small mut" style="margin:6px 0 0 16px">'+res.cambios.slice(0,8).map(function(c){ return '<li>'+esc(c[0])+' → '+esc(JSON.stringify(c[1])).slice(0,60)+'</li>'; }).join("")+(res.cambios.length>8?'<li>…</li>':'')+'</ul>'; } }
  return card("Importar situaciones",
    '<textarea rows="8" style="width:100%;font-family:monospace;font-size:12px" placeholder="Pega aquí el texto copiado (formato Copiar) y pulsa Revisar" onchange="'+on(function(v){ ST.sel.impTxt=v; ST.sel.impRes=null; go(); })+'">'+esc(txt)+'</textarea>'
    +resumen
    +'<div class="row" style="margin-top:10px;gap:8px">'
      +btn("Pegar del portapapeles",function(){ if(!navigator.clipboard||!navigator.clipboard.readText){ toast("Pega el texto a mano en el cuadro"); return; } navigator.clipboard.readText().then(function(t){ ST.sel.impTxt=t; ST.sel.impRes=null; go(); }, function(){ toast("El navegador no deja leer el portapapeles: pégalo a mano"); }); },"sm")
      +btn("Revisar",function(){ ST.sel.impRes=sitRevisar(ST.sel.impTxt||""); go(); },"sm")
      +'<span class="sp"></span>'
      +btn("Cerrar importación",function(){ ST.tab.imp=false; go(); },"sm")
      +btn("Guardar",sitGuardar,"sm gold")
    +'</div>');
}
