    var grupos=[["En juego",G.SITS,"si.j"],["Banquillo",G.SITS_BANQUILLO,"si.b"],["Te cambian",G.SITS_CAMBIO,"si.c"],["Momento decisivo",G.SITS_CLUTCH,"si.k"]], items=[], cur=null, q=(ST.sel.sq||"").toLowerCase();
