    var tabsCat='<div class="tabs" style="flex-wrap:nowrap;width:100%;overflow-x:auto;margin-bottom:14px">'+SIT_CAT_ORDEN.map(function(c){ var n=todas.filter(function(e){ return catSit(e.x.id,e.grp)===c; }).length; return '<button style="flex:1 1 0;min-width:0;padding:6px 4px;line-height:1.25;text-align:center;font-size:13px" class="'+(sc===c?"on":"")+'" onclick="'+on(function(){ST.tab.sc=c;go()})+'">'+esc(c)+'<br><small class="mut" style="font-weight:500">'+n+'</small></button>'; }).join("")+'</div>';
