V.mundo=function(){
  var k=ST.sel.mw||"club:BAR", pp=k.split(":"), O=ST.sel.mwo=ST.sel.mwo||{ES:true,EU:true}, det, rows="";
  CL.forEach(function(x){ reg("eq."+x.id+".elo",x.elo,x.c+" · Elo"); reg("eq."+x.id+".n",x.n,x.c+" · nombre"); });
  if(pp[0]==="club"){ var lc=ligaDe(CLI[pp[1]]); if(O[lc.id]===undefined) O[lc.id]=true; }
  var row=function(key,depth,label,rt,kids,oid,ch){ var open=!!O[oid]; return '<div class="it tr'+depth+(k===key?" on":"")+'" onclick="'+on(function(){ if(kids && (k===key || !open)) O[oid]=!open; ST.sel.mw=key; go(); })+'">'+(kids?'<span class="cv'+(open?"":" c")+'" onclick="'+on(function(v,el,ev){ ev.stopPropagation(); O[oid]=!open; go(); })+'">▼</span>':'<span class="cv0"></span>')+label+(ch?'<span class="ch"></span>':'')+'<span class="rt">'+(rt||"")+'</span></div>'; };
  PAIS.forEach(function(p){ var cs=COMPS.filter(function(c){return c.pais===p.id});
    rows+=row("pais:"+p.id,0,p.ban+" <b>"+esc(p.n)+"</b>",cs.length+" comp.",true,p.id,chgPre("pa."+p.id+"."));
    if(O[p.id]) cs.forEach(function(c){ var liga=c.tipo==="Liga", cl=liga?CL.filter(function(e){return e.d===c.d}):[];
      rows+=row("comp:"+c.id,1,esc(c.n),liga?cl.length+" clubes":c.tipo==="Copa"?"copa":"europea",liga,c.id,chgPre("lg."+c.id+"."));
      if(liga && O[c.id]) cl.forEach(function(e){ rows+=row("club:"+e.id,2,crest(e)+" "+esc(val("eq."+e.id+".n")),val("eq."+e.id+".elo"),false,"",chgPre("eq."+e.id+".")||chgPre("pl."+e.id+".")); }); }); });
  var titulo;
  if(pp[0]==="pais"){ var P=PAIS.filter(function(p){return p.id===pp[1]})[0]; det=paisDet(P); titulo=P.ban+" "+P.n; }
  else if(pp[0]==="comp"){ var C=COMPS.filter(function(c){return c.id===pp[1]})[0], Pc=PAIS.filter(function(p){return p.id===C.pais})[0]; det=compDet(C); titulo='<a class="lnk" onclick="'+on(function(){irMundo("pais:"+Pc.id)})+'">'+Pc.n+'</a> › '+esc(C.n); }
  else { var e=CLI[pp[1]]||CLI.BAR, l=ligaDe(e), Pl=PAIS.filter(function(p){return p.id===l.pais})[0]; det=clubDet(e); titulo='<a class="lnk" onclick="'+on(function(){irMundo("pais:"+Pl.id)})+'">'+Pl.n+'</a> › <a class="lnk" onclick="'+on(function(){irMundo("comp:"+l.id)})+'">'+l.n+'</a> › '+esc(e.n); }
  return hd("Mundo","Países, competiciones y clubes en un solo árbol. Elige a la izquierda y edita su ficha a la derecha.",btn("+ País",T("Crea un país nuevo, vacío"))+" "+btn("+ Competición",T("Crea una liga o una copa en el país elegido"))+" "+btn("+ Club",T("Crea un club en la liga elegida")))+
    '<div class="split"><div class="card list tree2">'+rows+'</div><div><div class="crumb" style="margin:2px 0 10px">'+titulo+'</div>'+det+'</div></div>';
};

