V.pantallas=function(){
  var s=ST.sel.pn||"P10", P=pById(s)||PANT[0], pre="pn."+P.id, L=P.id+" "+P.n, t=tabs("pn",["Datos","Comportamiento","Tiempos","Textos","Uso","Rediseño"]), tb=ST.tab.pn, b, items=[];
  PG.forEach(function(g){ items.push({gh:g[1]}); PANT.filter(function(p){return p.g===g[0]}).forEach(function(p){ reg("pn."+p.id+".est",PEST[p.id]||"Sin tocar",p.id+" · estado"); var e=val("pn."+p.id+".est"); items.push({id:p.id,n:p.id+" · "+p.n,rt:e==="Sin tocar"?"":e.toLowerCase(),ch:chgPre("pn."+p.id+".")}); }); });
  var desde=PANT.filter(function(x){return x.a.indexOf(P.id)>=0}).map(function(x){return x.id});
  if(tb==="Datos") b='<div class="grid g2">'+card(P.id+" · "+esc(P.n),
      '<div class="diff"><span class="p mut">Número</span><b class="mono">'+P.id+'</b></div>'+
      fld(pre+".n","Nombre",P.n,{full:L+" · nombre",d:"Solo para el panel."})+
      fld(pre+".g","Tipo",PG.filter(function(g){return g[0]===P.g})[0][1],{type:"sel",opts:PG.map(function(g){return g[1]}),full:L+" · tipo"})+
      '<div class="diff"><span class="p mut">En el código</span><span class="mono small">'+esc(P.fn)+'</span></div>'+
      (P.sub&&P.sub.length?'<div class="f"><label>Subpestañas<small>Se numeran '+P.id+'a, '+P.id+'b…</small></label><div>'+P.sub.map(function(x,i){var oc=(SUB_OCULTAS_ADMIN[P.id]||[]).indexOf(x)>=0; return '<span class="tag" style="margin:0 4px 4px 0'+(oc?';opacity:.5;text-decoration:line-through':'')+'" title="'+(oc?'Oculta en el juego':'Visible en el juego')+'">'+P.id+String.fromCharCode(97+i)+' '+esc(x)+(oc?' · oculta':'')+'</span>'}).join("")+'</div><div class="fab"></div></div>':"")+
      '<div class="f"><label>Se llega desde</label><div>'+(desde.map(pLink).join("")||'<span class="mut small">cualquier pantalla</span>')+'</div><div class="fab"></div></div>'+
      '<div class="f"><label>Lleva a</label><div>'+(P.a.map(pLink).join("")||'<span class="mut small">vuelve a donde estabas</span>')+'</div><div class="fab"></div></div>',
      P.nuevo?'<span class="tag vio">nueva</span>':"")+
    card("Activa en el juego",
      (function(){
        var hid=SUB_OCULTAS_ADMIN[P.id]||[];
        function sw1(key,lbl,def){ reg(key,def,P.id+" · "+lbl+" · activa"); return '<div class="diff"><span class="p">'+esc(lbl)+'</span>'+sw(val(key),function(){ set(key,!val(key)); })+'</div>'; }
        var H1=sw1(pre+".on",P.n,true);
        (P.sub||[]).forEach(function(x,i){ H1+=sw1(pre+".sub"+i+".on",x,hid.indexOf(x)<0); });
        return H1+'<p class="note" style="margin:8px 0 0">Apagado = no aparece en el juego. Sigue en el panel.</p>';
      })(),
      "")+
    card("Captura",'<div class="shot"><span class="mut">'+P.id+' · '+esc(P.n)+'</span></div><div class="row" style="margin-top:10px">'+btn("Tomar captura",T("Abre el juego en esa pantalla y guarda la imagen"),"sm")+btn("Abrir en el juego",T("Abre el juego directamente en "+P.id),"sm")+'<span class="small mut">Móvil 390 × 844</span></div>')+'</div>';
  else if(tb==="Comportamiento") b='<div class="grid">'+card("Al entrar y al salir",fld(pre+".in","Al entrar",P.in,{type:"area",rows:3,full:L+" · al entrar"})+fld(pre+".out","Al salir",P.out,{type:"area",rows:2,full:L+" · al salir"})+
      fld(pre+".fuera","Se cierra tocando fuera",P.g==="v",{type:"tog",full:L+" · se cierra tocando fuera",si:"Sí",no:"No"})+fld(pre+".menu","Muestra el menú inferior",P.g==="m",{type:"tog",full:L+" · menú inferior",si:"Sí",no:"No"})+
      (P.blq?'<div class="diff"><span class="p mut">La apaga el interruptor</span><span class="tag gold">'+esc(FLAGS.filter(function(f){return f[0]===P.blq})[0][1])+'</span></div>':""))+
    card("Botones y gestos",P.bt.length?'<div class="ox"><table><tr><th>Botón</th><th>Qué hace</th><th>Lleva a</th></tr>'+P.bt.map(function(x,i){return '<tr><td>'+cel(pre+".b"+i+".l",x[0],{w:150,full:L+" · botón "+(i+1)})+'</td><td>'+cel(pre+".b"+i+".d",x[1],{w:240,full:L+" · botón "+(i+1)+" · qué hace"})+'</td><td>'+(x[2]?pLink(x[2]):'<span class="mut small">—</span>')+'</td></tr>'}).join("")+'</table></div>':'<p class="mut">No tiene botones: se cierra sola.</p>')+'</div>';
  else if(tb==="Tiempos") b=card("Tiempos de "+P.id,P.tm.length? P.tm.map(function(x,i){ return fld(pre+".t"+i,x[0]+" (ms)",x[1],{type:"range",min:0,max:Math.max(1000,x[1]*3),step:x[1]>=1000?100:10,full:L+" · "+x[0],d:x[2]}); }).join("")+'<p class="small mut" style="margin:12px 0 0">Los marcados «fijo en el código» necesitan un cambio en el juego para leerse desde aquí. Los del reloj ya se editan en '+'<a class="lnk" onclick="'+on(function(){nav("reloj")})+'">Reglas globales › Reloj</a>.</p>' : '<p class="mut">Esta pantalla no tiene esperas ni animaciones propias.</p>',btn("Probar",T("Abre el juego en "+P.id+" con estos tiempos"),"sm"));
  else if(tb==="Textos") b=card("Textos de "+P.id,P.tx.map(function(x,i){ return /, en |^Los |^Las /.test(x)||/Ambiente|Narración|Tu gol|Tu asistencia|Indecisión|Extras|Lo que puedes/.test(x)? '<div class="diff"><span class="p">'+esc(x)+'</span><span class="tag">se edita en su ficha</span></div>' : '<div class="f"><label>Texto '+(i+1)+'</label>'+cel(pre+".x"+i,x,{w:260,full:L+" · texto "+(i+1)})+'<div class="fab"></div></div>'; }).join(""));
  else if(tb==="Uso") b=kpis([["Visitas · 30 días",nf(P.us[0]),""],["Tiempo medio",P.us[1],"por visita"],["Parte de la sesión",P.us[2]+" %",""],["Salidas del juego aquí",Math.round(P.us[0]*0.012),"cierran el juego en esta pantalla"]])+'<div class="grid g2 mt">'+card("Visitas por día · 14 días",spark([3,5,4,7,6,9,8,6,11,9,12,14,10,13].map(function(v,i){return Math.max(0,Math.round(v*P.us[0]/160+((i*7+P.id.charCodeAt(2))%5)))})))+(P.sub&&P.sub.length?card("Por subpestaña",bars(P.sub.map(function(x,i){return [P.id+String.fromCharCode(97+i)+" "+x,Math.round(P.us[0]/(i+1.6))]}))):card("De dónde vienen",bars(desde.map(function(d,i){return [d+" "+pById(d).n,Math.round(P.us[0]/(i+1.3))]}))||'<p class="mut">Sin datos.</p>'))+'</div>';
  else b='<div class="grid g2">'+card("Estado",fld(pre+".est","Estado",PEST[P.id]||"Sin tocar",{type:"sel",opts:["Sin tocar","En rediseño","Hecha"],full:P.id+" · estado"})+fld(pre+".pri","Prioridad","Normal",{type:"sel",opts:["Baja","Normal","Alta"],full:L+" · prioridad"})+fld(pre+".nota","Qué cambiar",PNOTA[P.id]||"",{type:"area",rows:5,full:L+" · qué cambiar"})+
      '<div class="row" style="margin-top:12px">'+btn("Copiar para Claude",T("Copiado: "+P.id+" con comportamiento, tiempos y notas"),"gold")+'<span class="small mut">Incluye número, comportamiento, tiempos y lo que quieres cambiar.</span></div>')+
    card("Reportes que la nombran",REP.slice(0,P.id==="P21"||P.id==="P13"?1:0).map(function(r){return '<div class="diff"><span>'+r.ic+'</span><span class="p">'+esc(r.x)+'</span><span class="tag">'+r.de+'</span></div>'}).join("")||'<p class="mut">Ninguno.</p>')+'</div>';
  var i=PANT.indexOf(P);
  return hd("Pantallas","Cada pantalla del juego, numerada: qué hace, cuánto dura y qué quieres cambiar.",btn("‹",function(){ST.sel.pn=PANT[(i-1+PANT.length)%PANT.length].id;go()},"sm")+" "+btn("›",function(){ST.sel.pn=PANT[(i+1)%PANT.length].id;go()},"sm"))+'<div class="split">'+lst(items,P.id,function(id){ST.sel.pn=id;go()})+'<div>'+t+b+'</div></div>';
};
V.mapa=function(){
  var W=168, Hh=34, GX=188, pos={}, svg="", maxn=0;
  PG.forEach(function(g,gi){ var L=PANT.filter(function(p){return p.g===g[0]}); maxn=Math.max(maxn,L.length); L.forEach(function(p,i){ pos[p.id]=[14+gi*GX, 44+i*46]; }); });
  var Ht=60+maxn*46;
  PANT.forEach(function(p){ p.a.forEach(function(d){ var a=pos[p.id], b=pos[d]; if(!a||!b) return; var x1=a[0]+(b[0]>=a[0]?W:0), y1=a[1]+Hh/2, x2=b[0]+(b[0]>a[0]?0:(b[0]===a[0]?W:W)), y2=b[1]+Hh/2, dx=b[0]===a[0]?46:Math.abs(x2-x1)/2;
    if(b[0]===a[0]){ x1=a[0]+W; x2=b[0]+W; svg+='<path d="M'+x1+' '+y1+' C'+(x1+dx)+' '+y1+' '+(x2+dx)+' '+y2+' '+x2+' '+y2+'" class="ed"/>'; }
    else svg+='<path d="M'+x1+' '+y1+' C'+(x1+(x2>x1?dx:-dx))+' '+y1+' '+(x2+(x2>x1?-dx:dx))+' '+y2+' '+x2+' '+y2+'" class="ed"/>'; }); });
  PG.forEach(function(g,gi){ svg+='<text x="'+(14+gi*GX)+'" y="24" class="gt">'+g[1].toUpperCase()+'</text>'; });
  PANT.forEach(function(p){ var a=pos[p.id], e=val("pn."+p.id+".est")||PEST[p.id]||"Sin tocar", c=e==="En rediseño"?"#FFC24B":e==="Hecha"?"#4ade80":"#2a2f48";
    svg+='<g class="nd" onclick="'+on(function(){ST.sel.pn=p.id;nav("pantallas")})+'"><rect x="'+a[0]+'" y="'+a[1]+'" width="'+W+'" height="'+Hh+'" rx="8" style="stroke:'+c+'"/><text x="'+(a[0]+10)+'" y="'+(a[1]+21)+'"><tspan class="nn">'+p.id+'</tspan> '+esc(p.n.length>17?p.n.slice(0,16)+"…":p.n)+'</text></g>'; });
  var cnt=function(e){ return PANT.filter(function(p){ return (val("pn."+p.id+".est")||PEST[p.id]||"Sin tocar")===e }).length; };
  return hd("Mapa de pantallas","Todas las pantallas y cómo se pasa de una a otra. Toca una para abrir su ficha.")+
    kpis([["Pantallas",PANT.length,"numeradas P01 – P44"],["Sin tocar",cnt("Sin tocar"),""],["En rediseño",cnt("En rediseño"),"borde dorado"],["Hechas",cnt("Hecha"),"borde verde"]])+
    card("Mapa",'<div class="ox"><svg class="map" viewBox="0 0 '+(GX*PG.length+40)+' '+Ht+'" style="min-width:'+(GX*PG.length+40)+'px;height:'+Ht+'px">'+svg+'</svg></div>',"","mt")+
    card("Tiempos comunes a todas",fld("pn.c.boton","Respuesta de un botón al tocarlo (ms)",140,{type:"range",min:0,max:400,step:10,full:"Pantallas · respuesta de botón"})+fld("pn.c.sub","Cambio de subpestaña (ms)",150,{type:"range",min:0,max:600,step:10,full:"Pantallas · cambio de subpestaña"})+fld("pn.c.ventana","Aparición de una ventana (ms)",220,{type:"range",min:0,max:800,step:10,full:"Pantallas · aparición de ventana"})+fld("pn.c.reduce","Sin animaciones si el móvil lo pide",true,{type:"tog",full:"Pantallas · respetar «reducir movimiento»",si:"Sí",no:"No"}),"","mt");
};


