var TOOLS={piramide:"",talentos:""};
function toolDoc(k){ var bin=atob(TOOLS[k]), u=new Uint8Array(bin.length); for(var i=0;i<bin.length;i++) u[i]=bin.charCodeAt(i); return new TextDecoder("utf-8").decode(u); }
function montar(){ [].forEach.call(document.querySelectorAll("iframe[data-tool]"),function(f){ if(!f.getAttribute("data-on")){ f.setAttribute("data-on","1"); f.srcdoc=toolDoc(f.getAttribute("data-tool")); } }); }
function toolFrame(k){ return '<iframe class="tool" data-tool="'+k+'" title="'+k+'"></iframe>'; }
/* talentos: los datos del árbol salen del borrador del Admin */
function talentosParaArbol(L){ var out={}; G.TALENTO_ORDEN.forEach(function(r){ var loc=L[r]||{nodes:[]}, T=G.TALENTOS[r], cols={}; loc.nodes.forEach(function(n){ cols[n.id]=n.col; });
  var dv=function(id,f,b){ var k="ta."+r+"."+id+"."+f; return DRAFT.hasOwnProperty(k)? DRAFT[k] : b; };
  out[r]={name:T.name, icon:loc.icon||"◆", color:loc.color||"var(--gold)", desc:loc.desc||"", nodes:T.nodes.filter(function(n){ return !dv(n.id,"off",false); }).map(function(n){ return {id:n.id,row:+dv(n.id,"row",n.row),col:cols[n.id]||3,rank:+dv(n.id,"rank",n.rank),lvl:+dv(n.id,"lvl",n.lvl),req:n.req,cap:n.cap,n:dv(n.id,"n",n.n),d:dv(n.id,"d",n.d)}; })}; });
  return out; }
