  var pend=PIDEC.filter(function(d){ return val("pi."+d[0])==="Sin decidir"; }).length;
  if(tb==="Taller") b='<div class="flg"><span class="tag vio">diseño · no está en el juego</span><span class="small mut">El juego sigue sin pirámide y con edad mínima de 16. Mueve las reglas aquí; nada llega al juego hasta decidir e implementar.</span><span class="sp"></span>'+(pend?'<a class="lnk small" onclick="'+on(function(){ST.tab.pi="Decisiones pendientes";go()})+'">'+pend+' decisiones pendientes</a>':'<span class="tag ok">todo decidido</span>')+btn("Pasar al borrador",piPasar,"sm gold")+'</div>'+toolFrame("piramide");
  else if(tb==="Decisiones pendientes") b=card("Lo que falta por decidir · "+pend+" de "+PIDEC.length,PIDEC.map(function(d,i){ return fld("pi."+d[0],(i+1)+" · "+d[1],"Sin decidir",{type:"sel",opts:d[3],full:"Pirámide · "+d[1],d:d[2]}); }).join("")+'<p class="small mut" style="margin:12px 0 0">Las cuatro primeras son de puertas, rangos y bolsas (pestañas 1 a 4 del taller); las cuatro últimas, de entorno, formación y giros (pestaña 5). Con todo decidido se puede empezar la fase 1.</p>')+
    card("Plan una vez decidido",[["Fase 1","Mundo con varios niveles, clubes reales 2026-27 con B y C, edad mínima 14, puertas con opinión del club, tabla central de reglas por rango, entorno, formación y giros en el motor."],["Fase 2","Filiales: convocatorias, debut, ascenso y cesiones."],["Fase 3","Copa del Rey y pruebas."]].map(function(x){return '<div class="diff"><span class="tag">'+x[0]+'</span><span class="p">'+x[1]+'</span></div>'}).join("")+'<p class="small mut" style="margin:10px 0 0">Las divisiones y filiales nuevas se crearán en <a class="lnk" onclick="'+on(function(){nav("mundo")})+'">Mundo</a>, como competiciones y clubes.</p>',"","mt");
  else b='<div class="grid g2">'+card("Qué es del motor y qué es propuesta",'<div class="diff"><span class="tag ok">motor</span><span class="p">Media de salida, nivel inicial, techo y declive, ganancia de entreno, envejecimiento y sueldo. Copiadas tal cual, entre las marcas CORE-START y CORE-END.</span></div><div class="diff"><span class="tag vio">propuesta</span><span class="p">Puertas, rangos, bolsas, entorno, formación, plasticidad, giros y término de edad. Viven fuera del núcleo y son lo que se mueve.</span></div><p class="small mut" style="margin:10px 0 0">Al incrustarlo en el Admin el núcleo no se ha tocado: solo se han cambiado colores y tipografía.</p>')+
    card("Pruebas",'<div class="diff"><span class="p"><b class="mono">F87_piramide.js</b><br><span class="small mut">La calculadora da lo mismo que el motor real</span></span><b>25.726</b></div><div class="diff"><span class="p"><b class="mono">E2E_piramide.js</b><br><span class="small mut">Navegador real</span></span><b>303</b></div><div class="diff"><span class="p"><b class="mono">mutar_html.py</b><br><span class="small mut">Mutaciones: 14 del núcleo y 12 de la interfaz</span></span><b>26</b></div><div class="row" style="margin-top:10px">'+btn("Pasar las pruebas",T("Lanza F87 y E2E en el servidor y avisa del resultado"),"sm")+'<span class="small mut">Última pasada: versión 4.66.0</span></div>')+
    card("Regla de trabajo",'<p class="small" style="margin:0;line-height:1.6">Si cambias una regla en el taller, hay que reflejarla igual en el motor y volver a pasar las pruebas de equivalencia. Antes de tocar progresión, talentos o atributos, lee <span class="mono">design-principles.md</span>.</p>')+'</div>';
