function buscar(q){
  q=q.toLowerCase().trim(); if(q.length<2){ $("sres").innerHTML=""; return; } var R=[];
  NAV.forEach(function(g){ g[1].forEach(function(i){ if(i[2].toLowerCase().indexOf(q)>=0) R.push([i[2],g[0],function(){nav(i[0])}]); }); });
  JUG.forEach(function(j){ if((j.n+j.id).toLowerCase().indexOf(q)>=0) R.push([jNom(j),"Usuario",function(){ST.sel.jug=j.id;ST.tab.jd="Ficha";nav("jugadores")}]); });
  CL.forEach(function(e){ if(e.n.toLowerCase().indexOf(q)>=0) R.push([e.n,"Club",function(){ST.tab.clb="Datos";irMundo("club:"+e.id)}]); });
  Object.keys(G.PLANT).forEach(function(k){ G.PLANT[k].forEach(function(j){ if(j[0].toLowerCase().indexOf(q)>=0) R.push([j[0],"Plantilla · "+CLI[k].c,function(){ST.tab.clb="Plantilla";irMundo("club:"+k)}]); }); });
  G.SITS.concat(G.SITS_BANQUILLO,G.SITS_CAMBIO,G.SITS_CLUTCH).forEach(function(s){ var t=isFn(s.t)?s.id:s.t; if((t+s.id).toLowerCase().indexOf(q)>=0) R.push([t,"Situación",function(){ST.sel.si=s.id;ST.sel.sq="";nav("situaciones")}]); });
  G.TALENTO_ORDEN.forEach(function(r){ G.TALENTOS[r].nodes.forEach(function(n){ if(n.n.toLowerCase().indexOf(q)>=0) R.push([n.n,"Talento · "+G.TALENTOS[r].name,function(){ST.tab.ta=r;ST.sel.ta=n.id;nav("talentos")}]); }); });
  G.ENTRENOS.forEach(function(e){ if(e.n.toLowerCase().indexOf(q)>=0) R.push([e.n,"Entrenamiento",function(){ST.sel.en=e.id;nav("entrenos")}]); });
  G.SKILLS.forEach(function(e){ if(e.n.toLowerCase().indexOf(q)>=0) R.push([e.n,"Habilidad",function(){ST.sel.sk=e.id;ST.tab.ju="Habilidades";nav("personaje")}]); });
  G.TIENDA_CATS.forEach(function(e){ if(e.n.toLowerCase().indexOf(q)>=0) R.push([e.n,"Tienda",function(){ST.sel.ti=e.id;ST.tab.ti="Tienda";nav("tienda")}]); });
  MOTOR.forEach(function(g){ g[1].forEach(function(m){ if(m[1].toLowerCase().indexOf(q)>=0) R.push([m[1],"Ajuste · "+g[0],function(){ST.sel.mq=m[1];nav("motor")}]); }); });
  PANT.forEach(function(x){ if((x.id+" "+x.n).toLowerCase().indexOf(q)>=0) R.push([x.id+" · "+x.n,"Pantalla",function(){ST.sel.pn=x.id;nav("pantallas")}]); });
  COMPS.forEach(function(l){ if(l.n.toLowerCase().indexOf(q)>=0) R.push([l.n,"Competición",function(){irMundo("comp:"+l.id)}]); });
  COD.forEach(function(c){ if(c.c.toLowerCase().indexOf(q)>=0) R.push([c.c,"Código",function(){ST.tab.cd="Códigos";nav("codigos")}]); });
  window._SR=R.slice(0,14);
  $("sres").innerHTML= R.length? '<div class="sres">'+window._SR.map(function(r,i){return '<div onmousedown="_SR['+i+'][2]();$(\'q\').value=\'\';$(\'sres\').innerHTML=\'\'"><b>'+esc(r[0])+'</b><span>'+esc(r[1])+'</span></div>'}).join("")+'</div>' : '<div class="sres"><div class="mut">Nada con «'+esc(q)+'»</div></div>';
}
$("q").addEventListener("input",function(){ buscar(this.value); });
$("q").addEventListener("blur",function(){ setTimeout(function(){ $("sres").innerHTML=""; },150); });
$("q").addEventListener("focus",function(){ buscar(this.value); });
