function pbArqDe(dis, ego, temp){
  /* el temperamento manda cuando es extremo: el guerrero existe en cualquier banda */
  if(temp!==undefined && temp>=74 && dis>=-35 && ego<55) return G_ARQ.guerrero;
  if(dis>=45){
    if(ego>=45) return G_ARQ.crack;
    if(ego<=-40) return G_ARQ.soldado;
    return G_ARQ.capitan;
  }
  if(dis>=15){
    if(ego>=35) return G_ARQ.crack;
    if(ego<=-25) return G_ARQ.soldado;
    return G_ARQ.capitan;
  }
  if(dis>=-29){
    if(ego>=60) return G_ARQ.showman;
    if(ego>=30) return G_ARQ.crack;
    if(ego<=-25) return G_ARQ.soldado;
    return G_ARQ.peon;
  }
  if(dis>=-44){
    if(ego>=55) return G_ARQ.showman;
    if(ego>=30) return G_ARQ.crack;
    return G_ARQ.problema;
  }
  if(ego>=45) return G_ARQ.genio;
  return G_ARQ.problema;
}
